            ['idapplication' => '829', 'emergency_contact' => false, 'parent_div_sep' => false, 'dob' => '2001-09-14', 'gender' => false, 'email_address' => 'lukehe1@btinternet.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'A Rotarian recommended it', 'firstname' => 'Luke', 'surname' => 'Hinkin-Evans', 'address' => '30 Grange Gardens', 'city' => 'Llantwit Major', 'county' => 'Wales', 'postcode' => 'CF61 2XB', 'contact_no' => '', 'alt_contact_no' => '+44 7860 808312', 'parent_1' => 'Simon Paul Evans', 'parent_2' => 'Natasha Hinkin-Evans', 'application_no' => '3720', 'citizen_of' => 'UK', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Luke', 'parent_support' => false, 'dyeo_id' => '1150', 'realm' => 'USER', 'application_status' => 'Accepted', 'application_status_note' => 'Paid Admin Fee', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'paulevans76@btinternet.com', 'parent2_email' => 'n.hinkinevans@btinternet.com', 'parent1_tel' => '', 'parent2_tel' => '', 'parent1_mobile' => '+44 7811 465660', 'parent2_mobile' => '+44 7855 148771', 'parent1_btel' => '', 'parent2_btel' => '', 'parent1_occupation' => 'Engineer', 'parent2_occupation' => 'Occupational Therapist', 'religion' => 'Atheist', 'diet_restriction' => 'None', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => false, 'treated_condition' => true, 'prescribed_meds' => true, 'special_req' => false, 'medical_info' => 'Had an operation to remove an osteochondroma from left knee. Injury has now fully recovered and wound is sealed. I have had a course of flucloxacillin for an infection after surgery.', 'rotary_club_id' => '19656', 'free_activities' => 'I spend countless hours in both organised and self-driven sporting activity. I coach and compete in gymnastics at least twice a week. I play rugby and football and have played for amateur teams in both sports. I have trained with community Circus\', NoFitState and Organised Kaos. I am a keen musician. I can play guitar and sing. I have had leading roles in school musicals. I compÃ¨re musical events in my school. I help Llantwit Major and Cowbridge Rotary clubs in their charitable work.', 'attainment_vocation' => 'So far in school I have achieved GCSEs and AS Level qualifications, and I am striving to obtain my A-Levels this year. Both my GCSEs and AS Levels are to a high standard and I look to continue that this year. Also, I have first aid, Disability Inclusion, Sports Leadership Levels 1&2 training through being selected onto the Vale of Glamorgan Coaches of the Future programme run by the local council. In addition, I have completed an online archaeology course about the development of the Palatine hill in Rome, arranged by the Sapienza University of Rome. Further, I have taken many acting & singing roles in school performances.', 'special_interests' => 'My special interests are sport, culture, human advancements and travel. I have trained in a wide variety of sports ranging from all football, rugby, trampolining and gymnastics. Through this I have developed a varied and adaptable skillset for all situations. Also, I have always been intrigued by how culture and tradition changes across the world and what led those changes to occur. I take joy in learning new customs and engaging with people from different countries and religions as it helps to broaden my mindset to understand all sects of humanity.This is why I would love to delve into travelling. ', 'special_skills' => 'I am a confident speaker which enables me to communicate well in new situations and to individuals and groups of all ages. I believe I am approachable and can put people at ease and act appropriately in an array of situations. I am a practical person so I like to get stuck in and get involved in any task. My \'can do\' attitude means I am always willing to develop my existing skills and help others to grow and learn alongside me.', 'contrib_entertainment' => 'I can contribute to entertainment, as I can play the guitar and I can sing. I would be able to start off and sing songs that all members of the trip can join in on, leading to a group bonding through language barriers as music is a universal joy. Also through gymnastics and my time in the circus I have many tricks and talents that I can display and hopefully help others on the trip to learn. ', 'reason_for_camp' => 'I chose to partake in this programme as I want to experience a new adventure outside my usual surroundings and to try something different. I wish to learn about various cultures. Our similarities and differences and what makes us all unique. This will help develop my general understanding of the world we live in today and what brings us all together. I want to discover the world and see all of its incredible sights and meet fantastic new people with whom I can create lifelong friendships.', 'personal_remarks' => '', 'place_of_birth' => 'Bridgend, Wales', 'em_name' => 'Valerie Hinkin', 'em_relationship' => 'Grandmother', 'em_htel' => '+44 1267 221192', 'em_mobile' => '', 'em_email' => '', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3720.png', 'date_of_app' => '2019-09-01 08:59:00'],
            ['idapplication' => '830', 'emergency_contact' => false, 'parent_div_sep' => false, 'dob' => '2003-09-19', 'gender' => false, 'email_address' => 'rexezard@gmail.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => false, 'how_did_you_hear' => 'A friend told me about it', 'firstname' => 'Rex', 'surname' => 'Ezard', 'address' => '61 Mary Street', 'city' => 'Porthcawl', 'county' => 'Bridgend', 'postcode' => 'CF36 3YN', 'contact_no' => '', 'alt_contact_no' => '+44 7722 710856', 'parent_1' => 'Diane Ezard', 'parent_2' => 'Andrew Ezard', 'application_no' => '3721', 'citizen_of' => 'UK', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Rex', 'parent_support' => false, 'dyeo_id' => '1150', 'realm' => 'USER', 'application_status' => 'Placed', 'application_status_note' => 'Paid Admin Fee. GER01 - Enjoy Saxony 2020', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'dezard@hotmail.co.uk', 'parent2_email' => 'andyezard1@gmail.com', 'parent1_tel' => '', 'parent2_tel' => '', 'parent1_mobile' => '+44 7798 2404645', 'parent2_mobile' => '+44 7850 381524', 'parent1_btel' => '+44 1792 229800', 'parent2_btel' => '', 'parent1_occupation' => 'Technician', 'parent2_occupation' => 'Salesman', 'religion' => 'Anglican', 'diet_restriction' => 'None', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => false, 'treated_condition' => false, 'prescribed_meds' => false, 'special_req' => false, 'medical_info' => '', 'rotary_club_id' => '19670', 'free_activities' => 'I enjoy running, cycling, swimming (Pencoed Tri-athlon Club and Bridgend Athletics Club), playing the piano and reading.  I also enjoy playing pool.', 'attainment_vocation' => 'I am currently studying for my GCSEs, which I will sit in June 2020. My predicted grades for my various subjects are A and A*.  I intend to remain in school to study for A levels as I am particularly interested in pursuing a career in engineering.  I also enjoy learning languages and would  like to work abroad.  ', 'special_interests' => 'I am a peer mentor at school and a Leader for Active Young People Development - an organisation that tries to encourage young people to become engaged with sport and physical activity.  As a member of Bridgend Athletics Club I have helped the younger athletes with the training and skills development through a series of supervised sessions.  I am a level "Gold" Rookie Lifeguard.  I am a level 7 at the martial art, Tang Soo Do.  I am an advanced level skier and have achieved level 2 piano.', 'special_skills' => 'I am able to ski and play the piano.  I speak German and Welsh.', 'contrib_entertainment' => 'I am able to play the piano.', 'reason_for_camp' => 'I would very much like to experience diverse cultures and to immerse myself within their traditions and culture.  I enjoy meeting new people and would love the opportunity of meeting people from different cultures, backgrounds and those who have different interests to me.  I very much enjoy getting involved with activies and see Youth Exchange Camp as an amazing opportunity to do this.   ', 'personal_remarks' => ' I have travelled abroad independently and am self sufficient.  I socialise well and have a good sense of humour.  Whilst I am a team player, I am also comfortable leading, as captain of a six-a-side football team.  I am mature and sensible.', 'place_of_birth' => 'Bridgend, Wales, UK', 'em_name' => 'Gerald Ezard', 'em_relationship' => 'Grandfather', 'em_htel' => '+44 1656 784904', 'em_mobile' => '', 'em_email' => 'geraldezard@talktalk.net', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3721.png', 'date_of_app' => '2019-09-01 15:27:00'],
