            ['idapplication' => '841', 'emergency_contact' => false, 'parent_div_sep' => false, 'dob' => '1999-09-18', 'gender' => true, 'email_address' => 'jasmine.celtel@outlook.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'Presentation at School/College/University', 'firstname' => 'Jasmine', 'surname' => 'Celtel', 'address' => '13 Bishton Street', 'city' => 'Newport', 'county' => 'Wales', 'postcode' => 'NP190DB', 'contact_no' => '+44  1633 769440', 'alt_contact_no' => '+44 7941 544421', 'parent_1' => 'Marcel Celtel', 'parent_2' => 'Nicola Celtel', 'application_no' => '3733', 'citizen_of' => 'UK', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Jasmine', 'parent_support' => false, 'dyeo_id' => '1150', 'realm' => 'USER', 'application_status' => 'Accepted', 'application_status_note' => 'Paid Admin Fee', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'marcel.celtel@meworld.com', 'parent2_email' => 'n.celtel@ntlworld.com', 'parent1_tel' => 'N/A', 'parent2_tel' => 'N/A', 'parent1_mobile' => '+447545088050', 'parent2_mobile' => '+447545483725', 'parent1_btel' => '', 'parent2_btel' => '', 'parent1_occupation' => 'Teacher', 'parent2_occupation' => 'Teacher', 'religion' => 'Atheist', 'diet_restriction' => 'NONE', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => false, 'treated_condition' => false, 'prescribed_meds' => false, 'special_req' => false, 'medical_info' => '', 'rotary_club_id' => '19665', 'free_activities' => 'In my free time, I like to explore my immediate surroundings. I have found exciting music venues, open mic nights for singers and poets, I have attended magazine launches, discovered the coolest bars and the most cosy cafes. I love to these events and places with friends and by myself so that I can make new friends at the event. I am a very social person, and I love nothing more than to make new friends.', 'attainment_vocation' => 'I am very ambitious, so my greatest aspiration is to finish my BA in English Literature and Language from Oxford University with a First Class. This would be an incredible achievement, and one that would help me in my future career. I am working towards this goal by spending most of my time studying. Another goal of mine is to work with a great heritage organisation, like UNESCO World Heritage, because I believe in making history and heritage accessible to all.', 'special_interests' => 'I am most proud of my academic achievements, so receiving a place at Oxford University has been a great honour for me. I was also very proud when my school awarded me the Annual Academic Excellence Award. Outside of academia, singing in bars and community centres has been a big accomplishment for me, as it is very daunting to sing alone, but it is also very exciting. Similarly, attending the Rotary Youth Exchanges has made me very proud of my ability to be independent while being part of a group.', 'special_skills' => 'Being able to sing and play an instrument (a ukulele) is really cool. I\'ve been singing for as long as I can remember, but recently I have started performing in bars and community centres for an audience, instead of just for my friends and family.', 'contrib_entertainment' => 'Apart from my sense of humour that always goes down well with a group, my best contribution to any camp is my ability to play the ukulele and sing. I have taught my friends in the group how to play the ukulele, and as thanks for hosting, I played my host family their favourite song; Moon River. These qualities and skills have been very entertaining to previous groups.', 'reason_for_camp' => 'Sharing my culture and absorbing elements of the host camp\'s way of life, and the aspects of life that the other camp mates bring to the camp is the whole reason I love to participate. I have found it so helpful to make friends from all over the world and to find out how special everyone is, but also, that we\'re all alike in many ways.', 'personal_remarks' => '', 'place_of_birth' => 'Newport, Gwent, Wales', 'em_name' => 'Lorraine Lee', 'em_relationship' => 'Grandmother', 'em_htel' => 'N/A', 'em_mobile' => '+447986850318', 'em_email' => 'N/A', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3733.jpeg', 'date_of_app' => '2019-09-07 16:12:00'],
