            ['idapplication' => '879', 'emergency_contact' => false, 'parent_div_sep' => false, 'dob' => '2003-08-24', 'gender' => true, 'email_address' => 'aarathyt@hotmail.co.uk', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'A Rotarian recommended it', 'firstname' => 'Aarathy', 'surname' => 'Thusyanthan', 'address' => 'Stable View', 'city' => 'Ramsey', 'county' => 'Cambridgeshire', 'postcode' => 'PE26 2NR', 'contact_no' => '+44 1487 814258', 'alt_contact_no' => '+44 7884 248418', 'parent_1' => 'Arumugasamy Thusyanthan', 'parent_2' => 'Karthiga Thusyanthan', 'application_no' => '3774', 'citizen_of' => 'UK', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Aarathy', 'parent_support' => false, 'dyeo_id' => '1070', 'realm' => 'USER', 'application_status' => 'Accepted', 'application_status_note' => 'Paid Admin Fee', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'burystores@btinternet.com', 'parent2_email' => 'burystores@btinternet.com', 'parent1_tel' => '+44 1487 814258', 'parent2_tel' => '+44 1487 814258', 'parent1_mobile' => '+44 7917 611352', 'parent2_mobile' => '+44 7748 250481', 'parent1_btel' => '+44 1487 812303', 'parent2_btel' => '+44 1487 812303', 'parent1_occupation' => 'Post Master', 'parent2_occupation' => 'Shop Owner', 'religion' => 'Hindu', 'diet_restriction' => 'None', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => true, 'treated_condition' => false, 'prescribed_meds' => false, 'special_req' => false, 'medical_info' => 'I have had fixed braces since Februrary 2019. ', 'rotary_club_id' => '19146', 'free_activities' => 'I practice my 2 instruments: playing leisurely and completing grades. I am currently working towards a Grade 8 in both the piano and the flute. In addition to this, I play table tennis at a local club, allowing me to stay physically active. Due to my job at the local Post Office, I attend regular shifts, in which I interact and engage with all generations in a helpful manner. ', 'attainment_vocation' => 'Currently, I attend The King\'s (The Cathedral) School in Peterborough, for which I have been there for the past 5 years.I have 10 GCSE grades: 8 9s and 2 8s. Presently, I am studying 3 A-Levels: Maths, Chemistry and Economics. In the future, I would like to complete a degree in economics, with hope of a financial economics career subsequently. ', 'special_interests' => 'I enjoy researching about international economics; in particular Middle Eastern and Asian economics. I have participated in the UKMT Maths Challenge 4 times, for which I have achieved 1 gold, 2 silvers and 1 bronze. During my extended holiday, I volunteered at the Ramsey Library as a listener of the national \'Summer Reading Challenge\'. I am part of a team in the \'Young Enterprise\' competition, serving as an operations director in our newly-established business. Similarly, I am participating in the national \'Student Investor\' Challenge, virtually buying and selling shares in the hope of obtaining profit. ', 'special_skills' => 'I have a Grade 6 Merit in the piano and a Grade 5 Distinction in the flute, as well as a Grade 5 Music Theory qualification. ', 'contrib_entertainment' => 'I can play the piano and the flute to a high standard, so can perform to an audience if a piano is available/I bring my flute. I have performed in a number of concerts for both instruments: solo and within an orchestra. ', 'reason_for_camp' => 'I would like to go to different parts of the world, particularly countries I would not expect to go to. It is also a way for me to meet new friends around the globe, and find out about different cultures that other teenagers interact with. In addition, my friends did this last year and extremely enjoyed it, which encouraged me to join.', 'personal_remarks' => '', 'place_of_birth' => 'Edgware, Middlesex, UK', 'em_name' => 'Shakira Coulston', 'em_relationship' => 'Family Friend', 'em_htel' => '+44 7595 624537', 'em_mobile' => '+44 7595 624537', 'em_email' => 'shakibabe@live.com', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3774.png', 'date_of_app' => '2019-09-24 21:50:00'],
