            ['idapplication' => '892', 'emergency_contact' => false, 'parent_div_sep' => false, 'dob' => '2002-10-13', 'gender' => true, 'email_address' => 'meganread02@gmail.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'Presentation at School/College/University', 'firstname' => 'Megan', 'surname' => 'Read', 'address' => '4 Kedleston Road, Park Farm', 'city' => 'Peterborough', 'county' => 'Cambridgeshire', 'postcode' => 'Pe2 8xl', 'contact_no' => '+44 1733 319158', 'alt_contact_no' => '+44 7512 616938', 'parent_1' => 'Mrs Julie Newman-Read', 'parent_2' => 'Mr David Read', 'application_no' => '3787', 'citizen_of' => 'UK', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Megan', 'parent_support' => false, 'dyeo_id' => '1070', 'realm' => 'USER', 'application_status' => 'Accepted', 'application_status_note' => 'Paid Admin Fee', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'meganannabelle@ntlworld.com', 'parent2_email' => 'dave.read@xaar.com', 'parent1_tel' => '+44 1733 319158', 'parent2_tel' => '+44 1733 319158', 'parent1_mobile' => '+44 7876 357848', 'parent2_mobile' => '+44 7825 095765', 'parent1_btel' => '', 'parent2_btel' => '+44 7825 095765', 'parent1_occupation' => 'Beauty Therapist', 'parent2_occupation' => 'Materials & Logistics Manager', 'religion' => 'Christianity', 'diet_restriction' => 'Vegetarian', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => false, 'treated_condition' => false, 'prescribed_meds' => true, 'special_req' => false, 'medical_info' => 'Penicillin for tonsilitis.', 'rotary_club_id' => '19158', 'free_activities' => 'During my free time I enjoy researching beyond my subject curriculum in areas of biology I\'m interested in as it a subject I wish to pursue at university. Additionally, I like watching a broad variety of YouTube videos that address topics such as the origin of diseases and developments in treatment. Twice a week, I play netball at school in order to have a break from my studies and to communicate with people I wouldn\'t usually see. ', 'attainment_vocation' => 'So far I have achieved getting impressive GCSE results, consisting of 2 A** (English language, religious studies) , 4 A* (maths, sciences, German, English Literature) and 2 A\'s (history, health and fitness). I have decided to take biology, chemistry and religious studies at A Level and aspire to take biomedical sciences at a prestigious university in the near future.', 'special_interests' => 'For many years now I have shown a passion in environmental issues and taking care of our ecosystems. Ways in which I have shown this is by educating others on world issues, cutting down on single-use plastic, subscribing to social-action Instagram pages and becoming a vegetarian. I\'m extremely passionate on topics regarding the environment and conservation and hope to go volunteering in countries abroad to help in any way I can.', 'special_skills' => 'From an early age I have been swimming and have had the opportunity to participate in races for my school on many occasions. Throughout this time I have gained many certificates including my 2000m swimming accomplishment. Even after quitting swimming classes to focus on my studies, I continue to show my skill for swimming whenever I go on holiday by spending many hours in the ocean and swimming pool.', 'contrib_entertainment' => 'Whilst I don\'t have any particular skills to be demonstrated, I will always participate regardless of what the entertainment is. I am particularly friendly with others and would be sure to provide a welcoming atmosphere to ensure everyone feels included and comfortable.', 'reason_for_camp' => 'There are many reasons for my application for rotary exchange: I am hopeful that it will be a memorable experience that can provide me with life-long skills and memories. I hope to improve my confidence and communication skills with others by making new friends from a variety of cultures. Additionally, travelling away from my home country and family will provide me with the opportunity to show independence and prepare me for my future solo and group expeditions across the world.', 'personal_remarks' => 'Nothing further to add.', 'place_of_birth' => 'Peterborough, UK', 'em_name' => 'Charlotte Newman', 'em_relationship' => 'Sister', 'em_htel' => '', 'em_mobile' => '+44 7715 602364', 'em_email' => '', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3787.png', 'date_of_app' => '2019-09-28 14:30:00'],
