            ['idapplication' => '901', 'emergency_contact' => false, 'parent_div_sep' => false, 'dob' => '2003-12-16', 'gender' => true, 'email_address' => 'inesmiranda78982@gmail.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'Other', 'firstname' => 'Ines Azevedo', 'surname' => 'Miranda', 'address' => 'Flat 3 Woodside, 147 Godstone Road, Whyteleafe', 'city' => 'Tandridge', 'county' => 'East Surrey', 'postcode' => 'CR3 0EH', 'contact_no' => '+44 20 8641 2568', 'alt_contact_no' => '+44 7495 257646', 'parent_1' => 'Anabela Miranda', 'parent_2' => '', 'application_no' => '3797', 'citizen_of' => 'UK', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Ines', 'parent_support' => false, 'dyeo_id' => '1145', 'realm' => 'USER', 'application_status' => 'Accepted', 'application_status_note' => 'Paid Admin Fee, Early Bird', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'anabelamiranda78982@gmail.com', 'parent2_email' => '', 'parent1_tel' => '+44 20 8641 2568', 'parent2_tel' => '', 'parent1_mobile' => '+44 7789 062922', 'parent2_mobile' => '', 'parent1_btel' => '', 'parent2_btel' => '', 'parent1_occupation' => 'Secretary', 'parent2_occupation' => '', 'religion' => 'Catholic', 'diet_restriction' => 'None', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => false, 'treated_condition' => false, 'prescribed_meds' => false, 'special_req' => false, 'medical_info' => '', 'rotary_club_id' => '20184', 'free_activities' => 'On one hand, I really enjoy practising sports such as swimming, cricket and football. On the other hand, I like to sketch and paint new pieces for my growing art collection. Fashion and photography are also one of my favourite topics to research, I like to look through second-hand shops and markets to pick out striking, alternative pieces and take photos of sites in London or elsewhere. ', 'attainment_vocation' => 'I\'m a hard-working student who aims to broaden my scope and knowledge of the outside world and also contribute positively to my environment, and fight for just causes that impact people of my generation. I\'m 16 years old and have only scratched the surface. ', 'special_interests' => 'Art is my main special interest because it is interactive and reflects my emotionally-driven personality and experiences. I am close to finishing my art GCSE course and wish to pursue the subject further. I also aim to practice my Spanish and Portuguese linguistic skills to a greater extent. I\'ve almost completed my secondary school curriculum and am keen to pursue my studies further alike my sister. ', 'special_skills' => 'I\'m a kind, funny and outgoing person who loves to meet new people and try new projects. I consider myself to be very determined and brave for my age, which can help me in the long-term once I travel and meet new people. ', 'contrib_entertainment' => 'I draw and sketch pieces and I continue to develop and professionalise those skills. I love to work with the most mundane equipment and build or colour them into something abstract but still able to resonate. Also, I love to talk and ask multiple questions hence making speeches and contributing to lectures is a key part of my contribution. ', 'reason_for_camp' => 'I want to gain more independence and challenge myself to travel abroad, and be able to manage on my own means in an unfamiliar place with new faces. I want to practice new sports and try different food, engage in diverse customs and make long-lasting friendships. It\'s the dream adventure for a 16 year old. These youth camps allow young people to embrace their freedom and enjoyment of being at this age.', 'personal_remarks' => '', 'place_of_birth' => 'Chelsea, London, England', 'em_name' => 'Tatiana Miranda', 'em_relationship' => 'Sister', 'em_htel' => '+44 7531 865111', 'em_mobile' => '', 'em_email' => 'tatianamiranda78982@gmail.com', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3797.png', 'date_of_app' => '2019-10-05 15:21:00'],
