            ['idapplication' => '922', 'emergency_contact' => false, 'parent_div_sep' => false, 'dob' => '2002-04-23', 'gender' => true, 'email_address' => 'eilisclaireohalloran@gmail.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'A Rotarian recommended it', 'firstname' => 'Eilis', 'surname' => 'O&#39;Halloran', 'address' => '7 Chestnut Grove, Bishopstown', 'city' => 'Cork', 'county' => 'Ireland', 'postcode' => 'T12 NXV8', 'contact_no' => '+353 87 6600467', 'alt_contact_no' => '+353 83 4622457', 'parent_1' => 'Claire O Halloran', 'parent_2' => 'Niall O&#39;Halloran', 'application_no' => '3822', 'citizen_of' => 'Republic of Ireland', 'other_info' => '?', 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'EilÃ­s', 'parent_support' => false, 'dyeo_id' => '1160', 'realm' => 'USER', 'application_status' => 'Accepted', 'application_status_note' => 'Paid Admin Fee', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'eckohalloran@outlook.com', 'parent2_email' => 'niallohalloran@hotmail.com', 'parent1_tel' => '+353 21 4341465', 'parent2_tel' => '+353 21 4341465', 'parent1_mobile' => '+353 87 6600467', 'parent2_mobile' => '+353 86 2539727', 'parent1_btel' => '', 'parent2_btel' => '', 'parent1_occupation' => 'Nurse', 'parent2_occupation' => 'Self Employed', 'religion' => 'None', 'diet_restriction' => 'None', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => false, 'treated_condition' => false, 'prescribed_meds' => false, 'special_req' => false, 'medical_info' => '', 'rotary_club_id' => '24130', 'free_activities' => 'I enjoy sports, especially swimming and running. I play the piano, and spend a lot of my free time practising. I love the French language, and enjoy watching movies (even though most of the time I don\'t understand what\'s going on) and reading (children\'s) novels in French to improve my skills. I also like art, especially watercolour painting.', 'attainment_vocation' => 'I completed my Junior Certificate in June 2018, and am currently in fifth year in secondary school. I am studying English, Irish, Maths, French, Applied Maths (Mechanics), Physics, Chemistry and Music. I hope to study something in the STEM field in University, possibly Chemical Engineering or Chemical Physics.', 'special_interests' => 'In May this year I was part of a team that won a silver medal for Ireland in the European Union Science Olympiad held in Portugal. Each team was made up of three members - a biologist, chemist and physicist. I was the chemist, and earned my place on the team after many rounds of selection tests prior to the Olympian. Along with chemistry, I enjoy maths, and was 2nd reserve for Ireland\'s European Girls Maths Olympiad team this year. Finally, I have completed piano grades I - VIII with RIAM, and am currently preparing for a diploma. I have also completed Speech and Drama grades I - VIII with LCM. ', 'special_skills' => 'I like to think I have good language and communication skills (though this might not necessarily be true).  I did quite a bit of figure skating and gymnastics when I was younger, and still hold on to many of those abilities (ie I can still do a cartwheel) . I work part-time as a barista, and can make many variations of coffee (though I\'m not sure this could be considered a special skill!)', 'contrib_entertainment' => 'I play piano to quite a high standard, and traditional Irish fiddle to an amateur level. ', 'reason_for_camp' => 'I can\'t think of a better way to spend my summer than to meet people from all over the world who share my interests. Participating in a youth camp seems like such a brilliant opportunity, and I would be a fool not to take it.', 'personal_remarks' => '', 'place_of_birth' => 'Cork, Ireland', 'em_name' => 'Fiona Kelleher', 'em_relationship' => 'Aunt', 'em_htel' => '+353 21 4377676', 'em_mobile' => '+353 87 9577232', 'em_email' => 'fikelleher@hotmail.com', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3822.png', 'date_of_app' => '2019-10-23 16:43:00'],
