            ['idapplication' => '924', 'emergency_contact' => false, 'parent_div_sep' => false, 'dob' => '2000-07-13', 'gender' => false, 'email_address' => 'tonyohalloran2000@gmail.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'Other', 'firstname' => 'Tony', 'surname' => 'O&#39;Halloran', 'address' => '7 Chetsnut Grove, Bishopstown', 'city' => 'Cork', 'county' => 'Ireland', 'postcode' => 'T12 NXV8', 'contact_no' => '', 'alt_contact_no' => '+353 86 0304020', 'parent_1' => 'Claire O&#39;Halloran', 'parent_2' => 'Niall O&#39;Halloran', 'application_no' => '3824', 'citizen_of' => 'Republic of Ireland', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => '', 'parent_support' => false, 'dyeo_id' => '1160', 'realm' => 'USER', 'application_status' => 'Accepted', 'application_status_note' => 'Paid Admin Fee', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'eckohalloran@outlook.com', 'parent2_email' => 'niallohalloran@hotmail.com', 'parent1_tel' => '', 'parent2_tel' => '', 'parent1_mobile' => '+353 87 6600467', 'parent2_mobile' => '+353 86 2539727', 'parent1_btel' => '', 'parent2_btel' => '', 'parent1_occupation' => 'Nurse', 'parent2_occupation' => 'Self Employed ', 'religion' => 'None', 'diet_restriction' => 'None', 'smoke' => false, 'smoke_why' => '', 'drink' => true, 'drink_why' => 'Occasional social drink. ', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => false, 'treated_condition' => false, 'prescribed_meds' => false, 'special_req' => false, 'medical_info' => '', 'rotary_club_id' => '24130', 'free_activities' => 'My main hobby is cycling, triathlons and adventure racing. I participated in my first bike race in 2010 and over the last nine years I\'ve been fortunate enough to be able to represent my province and to participate in a series of international events. I also participate in international debating in both B.P. Mace and EYP styles. This has afforded me many opportunities to meet new friends and to broaden my view of the world.', 'attainment_vocation' => 'I am currently studying Mathematical Sciences in University College Cork, having completed my Leaving Certificate in June 2019. In my Leaving Certificate I received top marks in most subjects including English, Mathematics, Physics and Business which meant I was lucky enough to receive a Gradam Award.  ', 'special_interests' => 'Member of Irish Mathematical Squad 2017-2019, Member of Irish Maths Team for 2018 Benelux Olympiad
Research published in Young Scientists Journal. Invited to Young Scientists Journal Conference 2017 in Cambridge
Presented research to Government Ministers in Dail Eireann as part of National Healthcare Policy Consultation Process (2017)
Research featured on TV3 and thejournal.ie, interviewed on Today FM and other media appearances.
Philisoph Debating Society Competition Munster and National Individual Finalist. European Youth Parliament National Finalist (2017 and 2018).', 'special_skills' => 'My experience debating has given me the ability to understand viewpoints which are very different to my own. This has allowed me to get make friends with people who are extremely different to me. I think that this is a good skill to have.', 'contrib_entertainment' => 'While my lack of musical talent prevents me from contributing to the entertainment on one level I hope that is made up for by my collection of party games and stories. I would also hope that my keen listening abilities would be an asset!  ', 'reason_for_camp' => 'My reason for programme participation is the sense of understanding and compassion that I feel comes with attending a youth camp. I am acutely aware the ability of these camps to connect the world and I feel that participation in a camp can help develop my interpersonal skills and make me more understanding of the world around me.', 'personal_remarks' => '', 'place_of_birth' => 'Cork, Ireland', 'em_name' => 'Fiona Kelleher', 'em_relationship' => 'Aunt', 'em_htel' => '', 'em_mobile' => '+353 87 9577232', 'em_email' => 'f.kelleher@outlook.com', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3824.png', 'date_of_app' => '2019-10-23 22:11:00'],
