            ['idapplication' => '926', 'emergency_contact' => false, 'parent_div_sep' => false, 'dob' => '2002-06-05', 'gender' => true, 'email_address' => 'em.cat.smith02@gmail.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'A Rotarian recommended it', 'firstname' => 'Emily', 'surname' => 'Smith', 'address' => '2 Hunter Close', 'city' => 'Rogerstone', 'county' => 'Newport', 'postcode' => 'NP10 0AX', 'contact_no' => '+44 7737 781415', 'alt_contact_no' => '+44 7926 343891', 'parent_1' => 'Paul James Smith', 'parent_2' => 'Lisa Jane Smith', 'application_no' => '3826', 'citizen_of' => 'United Kingdom', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Emily', 'parent_support' => false, 'dyeo_id' => '1150', 'realm' => 'USER', 'application_status' => 'Accepted', 'application_status_note' => 'Paid Admin Fee', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'paul.smith126@hotmait.com', 'parent2_email' => 'lgwatkin@rocketmail.com', 'parent1_tel' => '01633660277', 'parent2_tel' => '01633660277', 'parent1_mobile' => '07737781415', 'parent2_mobile' => '07884553134', 'parent1_btel' => '', 'parent2_btel' => '', 'parent1_occupation' => 'Support Worker for Adults with Learning Disabilities', 'parent2_occupation' => 'Part time Careworker for Elderly', 'religion' => 'None', 'diet_restriction' => 'None', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => null, 'treated_condition' => false, 'prescribed_meds' => null, 'special_req' => false, 'medical_info' => 'I had Mefanamic Acid for menstrual pain, but I have stopped taking it.', 'rotary_club_id' => '19657', 'free_activities' => 'In my free time, I enjoy reading and learning about other cultures. I also listen to a lot of music. I am part of wellbeing and leading teams in school; I use my spare time to help others with their mental health and raise money for my school and charity.', 'attainment_vocation' => 'From my school, I have attained high grades in Mathematics, English, Sciences and other subjects at high school level. I am also doing some higher level work currently in Sociology, Psychology, Mathematics and Religious Studies. ', 'special_interests' => 'I have a special interest in mental health because of my experience. I am part of mental health teams in my school where I raise awareness and come up with ideas such as creating a mental health team where students help other students. I was also chosen for a leadership role in school where I fundraise for charity. I also did the Rotary Youth Leadership Award this year.', 'special_skills' => 'I consider my special skill to be communication and empathy. I have a lot of experience with helping others and I am very friendly. This helps people to share their issues with me.', 'contrib_entertainment' => 'I can sing, and I used to be in the choir at school. I am also quite good at drawing small detailed drawings called mandalas.', 'reason_for_camp' => 'I am choosing to go on Rotary Youth Exchange because I love culture. I would love to meet people from different places and talk with them to see how they live. I think that this is an amazing opportunity to do this! As well as this, I have enjoyed a scheme with Rotary International in the past, and and I would enjoy doing something alone before I go to university.', 'personal_remarks' => '', 'place_of_birth' => 'United Kingdom', 'em_name' => 'Louise Rockett', 'em_relationship' => 'Family friend', 'em_htel' => 'n/a', 'em_mobile' => '07856015829', 'em_email' => 'Carmichaelclan@hotmail.com', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3826.jpeg', 'date_of_app' => '2019-10-29 00:43:00'],
