            ['idapplication' => '935', 'emergency_contact' => true, 'parent_div_sep' => false, 'dob' => '2001-10-12', 'gender' => true, 'email_address' => 'rebeccadonaghy123@btinternet.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'Presentation at School/College/University', 'firstname' => 'Rebecca', 'surname' => 'Dobbin Donaghy', 'address' => '238 Clonmore Road', 'city' => 'Dungannon', 'county' => 'Tyrone', 'postcode' => 'Bt716hx', 'contact_no' => '+44 28 3885 2548', 'alt_contact_no' => '+44 7549 080610', 'parent_1' => 'Paddy Donaghy', 'parent_2' => 'Theresa Dobbin', 'application_no' => '3839', 'citizen_of' => 'UK', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Rebecca', 'parent_support' => false, 'dyeo_id' => '1160', 'realm' => 'USER', 'application_status' => 'Accepted', 'application_status_note' => 'Paid Admin Fee', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => '', 'parent2_email' => 'theresadobbin@msn.com', 'parent1_tel' => '+44 28 3885 2548', 'parent2_tel' => '', 'parent1_mobile' => '+44 7765 841194', 'parent2_mobile' => '+44 7775 786620', 'parent1_btel' => '', 'parent2_btel' => '', 'parent1_occupation' => 'Farmer', 'parent2_occupation' => '', 'religion' => 'Roman Catholic', 'diet_restriction' => 'Nut allergy', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => false, 'treated_condition' => false, 'prescribed_meds' => true, 'special_req' => true, 'medical_info' => 'I am allergic to nuts, I carry an EpiPen because of this. I have an underactive thyroid gland so i take a tablet every morning for this', 'rotary_club_id' => '19721', 'free_activities' => 'I am heavily involved in my local GAA club, Conmore  Robert Emmets, County Armagh, as a player, coach and a volunteer.
I enjoy performing arts and I am a member of two drama groups. I take part in acting, singing and dancing and I have performed in many theatres across the UK and Ireland.
I also enjoy playing music with my friends and family as I am part of a very musical family. I am a member of my local church choir.
', 'attainment_vocation' => 'I have completed my GCSEs. I attained 2 A* grades in mathematics and religious education, and 8 A grades in English, history, music, French, LLW, biology, chemistry and physics.
I am currently studying for my A Levels. I am studying English literature, history, media studies and mathematics
I hope to study politics, philosophy and economics and university
I wish to pursue a career in the media as a radio and TV news reader', 'special_interests' => 'As a sportswoman I have represented my club, school and county in both Gaelic football and Camogie. My greatest sporting achievement thus far was winning the All Ireland Football Championship with my school, this is the highest achievement attainable in the sport.
In terms of performing, I have been lucky enough to be a part of a touring production which travelled across the UK and Ireland including the West End of London. I am also a keen public speaker and I represented the N. Ireland Soroptomists at their annual North-South conference, speaking alongside many distinguished speakers and MEPs. I am deputy Head Girl of my school.', 'special_skills' => 'Through my role as a Youth Leader in my local youth club I am trained in first aid, heart start, use of a defibrillator and child protection. I am also trained in working with young people with disabilities.
I am also a qualified Gaelic games coach and referee.
