            ['idapplication' => '957', 'emergency_contact' => false, 'parent_div_sep' => true, 'dob' => '2000-09-14', 'gender' => true, 'email_address' => 'anamrizwan2k15@gmail.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'A Rotarian recommended it', 'firstname' => 'Anam', 'surname' => 'Rizwan', 'address' => '80 The Grange', 'city' => 'Raheen', 'county' => 'Limerick', 'postcode' => 'V94 E8WT', 'contact_no' => '', 'alt_contact_no' => '+353 89 2134012', 'parent_1' => 'Huma Nasir ', 'parent_2' => 'Rizwan Gul', 'application_no' => '3863', 'citizen_of' => 'Republic of Ireland', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Anam', 'parent_support' => false, 'dyeo_id' => '1160', 'realm' => 'USER', 'application_status' => 'Placed', 'application_status_note' => 'DEN02 Denmark - Camp Copenhagen 2020', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'thefairgreenclinic@hotmail.com ', 'parent2_email' => 'rizwan.gul@hse.ie', 'parent1_tel' => '+353 89 4208660', 'parent2_tel' => '+353 87 6620085', 'parent1_mobile' => '+353 89 4208660', 'parent2_mobile' => '', 'parent1_btel' => '', 'parent2_btel' => '', 'parent1_occupation' => 'Doctor', 'parent2_occupation' => 'Doctor ', 'religion' => 'Islam', 'diet_restriction' => 'Halal meat ', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => false, 'treated_condition' => false, 'prescribed_meds' => false, 'special_req' => false, 'medical_info' => '', 'rotary_club_id' => '56212', 'free_activities' => 'I am quite fond of nail art which is a skill I would like to share with others. I also really enjoy yoga as it helps with physical relaxation, as well as mental relaxation. ', 'attainment_vocation' => 'I was awarded the Junior Certificate Home Economics student of the year in 2015. This was awarded to me as I showed a great dedication towards producing high levels of work over a 3 year period. ', 'special_interests' => 'I have a special interest in volunteering. I really enjoy being able to give back to the community and people. I have volunteered with womens aid and St Vincents de Paul for many years. ', 'special_skills' => 'I have great teamwork skills. I enjoy group work led and like to ensure that everyone\'s views and opinions are heard. I am also incredibly motivated and am able to complete tasks to a high standard on my own. I am an experienced debater, public speaker and poetry reader. I have partaken in many competitions most recently being the University College Dublin Junior Debating competition. I was 1 of 8 students to take part in the final of this competition out of more than 150 students. ', 'contrib_entertainment' => '', 'reason_for_camp' => 'I would really love the opportunity to meet and work with people from different cultures. I enjoy learning about diverse cultures and traditions which i feel is best achieved by interacting with people from all over the world. ', 'personal_remarks' => '', 'place_of_birth' => 'Limerick, Ireland', 'em_name' => 'Sono Rizwan', 'em_relationship' => 'Brother', 'em_htel' => '', 'em_mobile' => '+353 87 6532054', 'em_email' => '', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3863.png', 'date_of_app' => '2019-12-05 15:43:00'],
