            ['idapplication' => '959', 'emergency_contact' => false, 'parent_div_sep' => true, 'dob' => '2002-02-17', 'gender' => true, 'email_address' => 'sophiezee9@gmail.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'Presentation at School/College/University', 'firstname' => 'Sophie', 'surname' => 'Zeeman', 'address' => '53 Gowers Walk', 'city' => 'London', 'county' => 'London', 'postcode' => 'E1 8BS', 'contact_no' => '', 'alt_contact_no' => '+44 7933 167417', 'parent_1' => 'Kathy Zeeman', 'parent_2' => '', 'application_no' => '3865', 'citizen_of' => 'UK', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Sophie', 'parent_support' => false, 'dyeo_id' => '1130', 'realm' => 'USER', 'application_status' => 'Accepted', 'application_status_note' => 'Paid Admin Fee. Possible San Diego violinist', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'kathyzee48@gmail.com', 'parent2_email' => '', 'parent1_tel' => '', 'parent2_tel' => '', 'parent1_mobile' => '+44 7880 620598', 'parent2_mobile' => '', 'parent1_btel' => '', 'parent2_btel' => '', 'parent1_occupation' => '', 'parent2_occupation' => '', 'religion' => 'Christian', 'diet_restriction' => 'None', 'smoke' => false, 'smoke_why' => '', 'drink' => true, 'drink_why' => 'Slightly and occasionaly at social events', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => false, 'treated_condition' => false, 'prescribed_meds' => true, 'special_req' => false, 'medical_info' => 'Salbutamol & Clenil; for mild asthma', 'rotary_club_id' => '19555', 'free_activities' => 'Music has always played a huge role in my life; I have attended music school every Saturday since the age of seven. I currently attend the Centre for Young Musicians, lead the Tower Hamlets Youth Orchestra, and am a member of the London Schools Symphony Orchestra. I am very creative, and so enjoy creating DIY\'s from unwanted packaging, knitting and paper cutting. I sometimes do voluntary dog walking and in the summer, I attend water sporting activities at my local sporting basin.', 'attainment_vocation' => 'Attainments = I was selected as artist of the term in year 9, mathematician of the term twice in year 10 and once in year 11, selected for the maths mentoring and paired reading programmes, promoted as leader of the school orchestra 4 years ago, was successful in getting to the ARTiculate (public speaking competition) school finals. I have hosted school events such as the Talent Show, Spring Music Concert and have single-handedly organised and hosted the sixth form Gig Night. Vocations = was a peer councillor in year 9, maths mentor, year 7 paired reader, Charity Rep and am currently Music Prefect. ', 'special_interests' => 'I am interested in the relationship between Psychology and Music; what intrigues me further is the disruption of the Phonological loop, due to deficit of Articulatory functions, and the questions of whether it is possible to still carry out phonological functions such as the holding of words we hear using the Primary acoustic store alone (to help those with reading difficulties). Accomplishments = was a Jack Petchy Speak Out Challenge regional finalist, specially selected to take part in the LSO Next Generation Scheme, graduated as a fire cadet, successfully got into the LSSO and promoted as the leader of the Tower Hamlets Youth Orchestra.
', 'special_skills' => 'I have a natural way with children and love to interact with them. I am extremely organised and so have a skill for arranging things in rooms to look aesthetically pleasing. I sometimes do voluntary dog walking, and so have experience with looking after dogs too. As I have helped out during many school open evenings from year 8 to year 13 by showing prospective parents around the school) and so I possess tour guiding experience and therefore good communication and people skills. Work experience at The Sound Learning Centre, I helped to administer \'Auditory Integration Training\' and LWS; I have thus gained skill in treating speaking deficits.', 'contrib_entertainment' => 'Yes; I am a grade 8 violinist and grade 4 pianist.', 'reason_for_camp' => 'I wish to grow further as a person (eg: in confidence) and learn about new cultures; I believe this opportunity will help to enhance my adaptability skills, which are key in any work place. I also wish to be adventureous and make new life long friends.', 'personal_remarks' => 'I am very much into trendy fashion and love sushi!', 'place_of_birth' => 'London, UK', 'em_name' => 'Lydia McCartney', 'em_relationship' => 'Close Family Friend', 'em_htel' => '', 'em_mobile' => '+44 7936 460103', 'em_email' => '', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3865.png', 'date_of_app' => '2019-12-05 21:53:00'],
