            ['idapplication' => '961', 'emergency_contact' => false, 'parent_div_sep' => false, 'dob' => '2001-11-26', 'gender' => false, 'email_address' => 'neongomane@gmail.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => false, 'how_did_you_hear' => 'Search engine', 'firstname' => 'Neo Brian', 'surname' => 'Ngomane', 'address' => '145 Gayhurst, Hopwood Road', 'city' => 'LONDON', 'county' => 'London', 'postcode' => 'SE17 2BN', 'contact_no' => '', 'alt_contact_no' => '+44 7751 9536127', 'parent_1' => 'Lerato Mohlala', 'parent_2' => '', 'application_no' => '3867', 'citizen_of' => 'South Africa (but resident in the UK)', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Neo', 'parent_support' => false, 'dyeo_id' => '1130', 'realm' => 'USER', 'application_status' => 'Accepted', 'application_status_note' => 'Paid Admin Fee', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'gemsgodiva2014@gmail.com', 'parent2_email' => '', 'parent1_tel' => '', 'parent2_tel' => '', 'parent1_mobile' => '+44 7508 265066', 'parent2_mobile' => '', 'parent1_btel' => '', 'parent2_btel' => '', 'parent1_occupation' => '', 'parent2_occupation' => '', 'religion' => 'Christian', 'diet_restriction' => 'None', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => false, 'treated_condition' => false, 'prescribed_meds' => false, 'special_req' => false, 'medical_info' => '', 'rotary_club_id' => '19538', 'free_activities' => 'In my leisure time, I partake in cricket rugby and hockey whenever I have the opportunity to however I have recently had to cut down on doing such activities as I have had to place greater attention to school and my education as I am in my final year of sixth from therefore to sort my attention accordingly.', 'attainment_vocation' => 'My most memorable attainments in school mostly came in primary school whereby I took part in the south African championships for cross-country running and Athletics. In this period of my education, I was also selected to play for my provincial hockey team and compete against other people my age around the country. In secondary school education I was given the responsibility of being a sports leader and for this achievement I received the jack patchy award for my contributions towards sports.', 'special_interests' => 'My special interest are mostly In sports and outdoor activities particularly cricket and hockey. I have recently become more interested in hiking skating and skiing, activities I once would have not had an interest in and deemed mundane. ', 'special_skills' => 'perhaps considered more a trait than a skill, however I am incredibly independent and believe I am an open book and therefore I find I make friends and create bonds with people relatively easily as I am an attentive individual and as such I rend to bond with many individuals, ', 'contrib_entertainment' => 'I do not have any artistic contributions to offer however as aforementioned, I have great abilities in hockey, cricket and rugby. ', 'reason_for_camp' => 'The main reason for my wanting to participate in the programme is due to my growing willingness to experiment in new activities and experience new cultures and lifestyles. I am revelling at the opportunity to meet people of different cultures and ethnicities to share experiences with and gain a greater knowledge of their customs first hand.', 'personal_remarks' => '', 'place_of_birth' => 'South Africa', 'em_name' => 'Saidi Yusuf', 'em_relationship' => '', 'em_htel' => '', 'em_mobile' => '+44 7785 3121697', 'em_email' => 'faruksala@yahoo.co.uk', 'country_citizenship' => null, 'image_location' => null, 'date_of_app' => '2019-12-08 21:10:00'],
