            ['idapplication' => '970', 'emergency_contact' => false, 'parent_div_sep' => false, 'dob' => '2001-07-09', 'gender' => true, 'email_address' => 'scutarudumitrita2001@gmail.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'Presentation at School/College/University', 'firstname' => 'Dumitrita', 'surname' => 'Scutaru', 'address' => '26 Rnafurly Crescent', 'city' => 'Dungannon', 'county' => 'Tyrone', 'postcode' => 'BT716PH', 'contact_no' => '+44 7518 477244', 'alt_contact_no' => '+44 7518 477244', 'parent_1' => 'Silvia Scutaru ', 'parent_2' => 'Dumitru Scutaru ', 'application_no' => '3876', 'citizen_of' => 'Romania ', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Domi ', 'parent_support' => false, 'dyeo_id' => '1160', 'realm' => 'USER', 'application_status' => 'Placed', 'application_status_note' => 'Paid Admin Fee', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'boss.scutaru@mail.ru ', 'parent2_email' => 'boss.scutaru@mail.ru', 'parent1_tel' => '', 'parent2_tel' => '', 'parent1_mobile' => '+44 7711 085614', 'parent2_mobile' => '+44 7845 514648', 'parent1_btel' => '', 'parent2_btel' => '', 'parent1_occupation' => 'Line worker ', 'parent2_occupation' => 'Mechanic ', 'religion' => 'Orthodox ', 'diet_restriction' => 'Vegetarian ', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'Romanian ', 'medical_condition' => false, 'treated_condition' => false, 'prescribed_meds' => false, 'special_req' => false, 'medical_info' => '', 'rotary_club_id' => '19721', 'free_activities' => 'As a creative spirit I love sketching and photography. In terms of sketching, I prefer pencil studies and love landscape and studio photography.  Beauty and skincare are some of my many passions.  also adore going to my local gym, I attend it 4 to 5 times a week which helps me keep fit and in shape.', 'attainment_vocation' => 'I am finishing my last year of school and can say that I love the subjects I have specialised in which are English Literature, mathematics, business studies and French. I have achieved 8 A* grades and 2 A grades at GCSE level study and 3A and 1B at AS level last year. I aspire to study Global Business with French in university next year which I am very excited for. Currently I work part-time in hospitality as well as keeping up with my studies. Having a part time job has truly helped me master my time management skills and efficiency with my work. I love interacting with customers.  I love my upbeat and busy lifestyle. ', 'special_interests' => 'In the past few years I have been very invested in my personal development. Last year I have volunteered for Rotary in their Christmas Tree of Hope program, which has helped me develop my interpersonal skills. I am also a trained Learn Spark mentor in my school where I help younger students if they are struggling with work. I have been part of many debates and competitions such as QUB literific debate and Bar National Mock Trial which have helped me develop my communication skills. I also have completed a challenge of camping in the Northern Irish mountains last summer in order to complete my Gold Award in Duke if Edinburgh. ', 'special_skills' => 'My linguistic skills are very developed, as I speak 5 languages. These have truly helped me overcome many situations in my life which I find very useful.  I would say that my communication skills have really helped me be an understanding, open and lively individual. Personally, I would describe my character as charming which makes it easy for me to be friendly and connect with those around me. My team work skills which I have developed from activities such as the Duke of Edinburgh award have helped me in especially last year when I was in another youth exchange camp. ', 'contrib_entertainment' => 'I am currently self taught in guitar and piano, where I can play simple melodies. ', 'reason_for_camp' => 'As I have been connected to Rotary for over a year now and have been part of their Youth Leadership Award, I believer this is the perfect opportunity to dive deeper in my desire to travel and expand my horizons. This is my second time applying to Rotary Youth Exchange, as I have already been part of the Flanders Camp last year. Due to my fantastic experience last year, I cannot wait to be part of it all again and meet new cultures and people. ', 'personal_remarks' => '', 'place_of_birth' => 'Chisinau,  Republic of Moldova ', 'em_name' => 'Ion Chistol ', 'em_relationship' => 'Close friend', 'em_htel' => '', 'em_mobile' => '+44 7752 132437', 'em_email' => 'ionelchistol7@gmail.com', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3876.png', 'date_of_app' => '2019-12-12 16:46:00'],
