            ['idapplication' => '983', 'emergency_contact' => false, 'parent_div_sep' => false, 'dob' => '2002-05-06', 'gender' => false, 'email_address' => 'feargalmckeever@outlook.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'Presentation at School/College/University', 'firstname' => 'Feargal', 'surname' => 'McKeever', 'address' => '17 Moorlands', 'city' => 'Coalisland', 'county' => 'Tyrone', 'postcode' => 'BT714SJ', 'contact_no' => '+44 28 8774 6295', 'alt_contact_no' => '+44 7796 488490', 'parent_1' => 'Deirdre McKeever', 'parent_2' => 'Aidan McKeever', 'application_no' => '3881', 'citizen_of' => 'Ireland', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Feargal', 'parent_support' => false, 'dyeo_id' => '1160', 'realm' => 'USER', 'application_status' => 'Accepted', 'application_status_note' => 'Paid Admin Fee', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'deemckeever@hotmail.com', 'parent2_email' => '', 'parent1_tel' => '+44 28 8774 6295', 'parent2_tel' => '+44 28 8774 6295', 'parent1_mobile' => '+44 7748 375200', 'parent2_mobile' => '+44 7979 526264', 'parent1_btel' => '', 'parent2_btel' => '', 'parent1_occupation' => 'Beautician', 'parent2_occupation' => 'Car mechanic', 'religion' => 'Christian', 'diet_restriction' => 'None', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => false, 'treated_condition' => false, 'prescribed_meds' => false, 'special_req' => false, 'medical_info' => '', 'rotary_club_id' => '19721', 'free_activities' => ' In my free time I like to exercise at the gym and work on my physical fitness as it is important to be healthy both physically and mentally. I also enjoy cooking healthy and tasty meals for myself and my family. I enjoy volunteer work too because it gets me outside of my comfort zone and I have made connections with people I otherwise wouldn\'t know today. Finally, I like to spend my free time with my family and my friends, either visiting local landmarks or just relaxing together.', 'attainment_vocation' => 'I am currently studying my final year in secondary school and so far I have achieved great scores in my exams. With ten GCSEs under my belt, I am on track for similar success in my A-Levels. Later this year I will be applying for my dream course at university, where I aspire to study International Business with a language. I find this course very interesting, the business part of it will be informative on how businesses trade with each other globally and the language aspect is also attractive as there are so many different languages spoken around the world.', 'special_interests' => 'I love to travel to different places with anyone! I think that it\'s the best way to make memories, especially when it\'s with people you barely know as it gives you a reason to get to now them better and some could turn out to become a best friend. I am also interested in languages, it\'s amazing how they can connect people together. I like volunteering, contributing to local communities and making a difference to the lives of both acquaintances and strangers. A special accomplishment of mine was when I ran 10KM in aid of suicide awareness. It took me a long time and I was exhausted at the time but I feel very proud of myself now for doing it.', 'special_skills' => 'I believe that I have great interpersonal and communication skills. I am always eager to meet new people and I don\'t mind breaking the ice with a simple \'Hello\'. I am also an active listener, it is import to have input but it is just as important to actually listen to what other people are saying. I always consider other peoples opinions and I am not afraid to admit if I am in the wrong.', 'contrib_entertainment' => 'I can play the tin whistle and I am currently learning to play the guitar. I can also do a backflip, which some people find to be entertaining. I think that the most important thing is that people describe me as an entertaining person. I can keep a conversation going but also know the appropriate time to stop.', 'reason_for_camp' => 'I would like to participate in the Rotary Youth Exchange of the great things I have heard about it. A few of my friends participated in it last year and they shared stories about how they enjoyed their time immensely. This reaffirmed my choice to apply as I love to meet different people from different backgrounds and experience different cultures.', 'personal_remarks' => 'I think that participating in a camp will broaden my horizons and it will help me to learn more about how different parts of the world work together.', 'place_of_birth' => 'Craigavon, Co. Armagh, Northern Ireland', 'em_name' => 'Celine O&#39;Donnell', 'em_relationship' => 'Grandmother', 'em_htel' => '+44 28 8774 8129', 'em_mobile' => '+44 7522 601836', 'em_email' => '', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3881.png', 'date_of_app' => null],
