            ['idapplication' => '994', 'emergency_contact' => false, 'parent_div_sep' => false, 'dob' => '2003-08-04', 'gender' => true, 'email_address' => 'AnnaCooney03@outlook.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'Presentation at School/College/University', 'firstname' => 'Anna', 'surname' => 'Cooney', 'address' => '194 Mullaghmore Road, Donaghmore', 'city' => 'Dungannon', 'county' => 'County Tyrone', 'postcode' => 'BT70 3ER', 'contact_no' => '+44 28 8776 9064', 'alt_contact_no' => '+44 7484 679064', 'parent_1' => 'Olivia Cooney', 'parent_2' => 'Julian Cooney', 'application_no' => '3900', 'citizen_of' => 'UK', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Anna', 'parent_support' => false, 'dyeo_id' => '1160', 'realm' => 'USER', 'application_status' => 'Placed', 'application_status_note' => 'NOR03 Norway - Nature, Art and Culture 2020', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'cooney300@btinternet.com', 'parent2_email' => 'cooney300@btinternet.com', 'parent1_tel' => '+44 28 8776 9064', 'parent2_tel' => '+44 28 8776 9064', 'parent1_mobile' => '+44 7765 658106', 'parent2_mobile' => '+44 7920 148547', 'parent1_btel' => '+44 28 8772 9695', 'parent2_btel' => '', 'parent1_occupation' => 'Finance Officer', 'parent2_occupation' => 'Stone mason', 'religion' => 'Roman Catholic', 'diet_restriction' => 'None', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => false, 'treated_condition' => false, 'prescribed_meds' => false, 'special_req' => false, 'medical_info' => '', 'rotary_club_id' => '19721', 'free_activities' => 'I have always been a voracious reader, devouring books of any genre, and as a result I also enjoy creative writing, especially short stories. I enjoy keeping fit, having joined a gym and participating in group challenges.', 'attainment_vocation' => 'Through my school, I competed in the Magistratesâ€™ Court Mock Trial Competition, and completed the POD workshop at the Corrymeela Community. In Year 10 I achieved 1st place in TrÃ¡th na gCeist Gael Linn with a group of my classmates. I achieved a Bronze certificate in the UK Mathematics Trust Junior Mathematical Challenge.
', 'special_interests' => 'I played piano, achieving my Grade 2 before i was forced to take a sabbatical due to a hand injury. I also volunteer at my local theatre on Saturday mornings. I work with the under-11 group, and help look after the children, organise them and assist backstage.', 'special_skills' => 'I am a keen cook and baker, and love giving my friends and family samples of what I make.', 'contrib_entertainment' => 'Whilst I don\'t play an instrument anymore, I am always eager to participate. I love all genres of music and have very wide and varied musical taste. ', 'reason_for_camp' => 'I am always keen to push myself out of my comfort zone, and challenge myself to do new things. I have always been fascinated by different cultures and languages, and have always loved travelling and am excited to meet new people. I also love the outdoors and exploring the world around me, and would love to go to a camp that allows me to experience what my host country has to offer.', 'personal_remarks' => '', 'place_of_birth' => 'Donaghmore, Dungannon, Co. Tyrone, UK', 'em_name' => 'Emma Faloon', 'em_relationship' => 'Aunt', 'em_htel' => '+44 28 8776 1885', 'em_mobile' => '+44 7729 808221', 'em_email' => 'emmafaloon@gmail.com', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3900.png', 'date_of_app' => '2019-12-20 12:38:00'],
