            ['idapplication' => '1010', 'emergency_contact' => false, 'parent_div_sep' => false, 'dob' => '2001-12-23', 'gender' => true, 'email_address' => 'ellenkirkland2001@gmail.com', 'school' => null, 'why_rotary' => null, 'consider_alt_country' => null, 'how_did_you_hear' => 'Presentation at School/College/University', 'firstname' => 'Ellen  Linda', 'surname' => 'Kirkland', 'address' => '19 Kilsannagh Lane', 'city' => 'Dungannon', 'county' => 'Tyrone', 'postcode' => 'BT70 1LR', 'contact_no' => '+44 28 3754 9407', 'alt_contact_no' => '+44 7393 358942', 'parent_1' => 'Jennifer Kirkland', 'parent_2' => 'Brian Kirkland', 'application_no' => '3918', 'citizen_of' => 'UK', 'other_info' => null, 'exchange_type' => 'CAMPS & TOURS', 'pref_name' => 'Ellen', 'parent_support' => false, 'dyeo_id' => '1160', 'realm' => 'USER', 'application_status' => 'Accepted', 'application_status_note' => '', 'dyeo_assigned' => true, 'application_fee' => null, 'application_fee_paid' => false, 'parent1_rotarian' => false, 'parent2_rotarian' => false, 'parent1_rotary_club' => '', 'parent2_rotary_club' => '', 'parent1_email' => 'jkirkland1975@yahoo.co.uk', 'parent2_email' => 'jkirkland1975@yahoo.co.uk', 'parent1_tel' => '+44 28 3754 9407', 'parent2_tel' => '+44 28 3754 9407', 'parent1_mobile' => '+44 7770 767316', 'parent2_mobile' => '+44 7788 377608', 'parent1_btel' => '', 'parent2_btel' => '', 'parent1_occupation' => '', 'parent2_occupation' => 'Farmer', 'religion' => 'Christian', 'diet_restriction' => 'None', 'smoke' => false, 'smoke_why' => '', 'drink' => false, 'drink_why' => '', 'illegal_drugs' => false, 'illegal_drugs_why' => '', 'native_language' => 'English', 'medical_condition' => false, 'treated_condition' => false, 'prescribed_meds' => false, 'special_req' => false, 'medical_info' => '', 'rotary_club_id' => '19721', 'free_activities' => 'I am heavily involved in my local church where I am a Sunday School teacher, helping the younger children, but also assisting and working as part of a team with the other teachers in preparation for special services. I have been a member of Girls Brigade since I was 7 which I attend every Monday night. I also enjoy taking part in local fitness classes and play for the school hockey team. Sports and music are something I have a keen interest in.', 'attainment_vocation' => 'Currently I am the head girl at The Royal School Dungannon whereby I undertake a number of roles including organising and speaking at events. Whilst studying here I have attained 7 A*\'s and 3A\'s at GCSE level and AAAB at AS level in Economics, Mathematics, Geography and Spanish. This summer I will be doing my A2 levels. ', 'special_interests' => 'I have achieved both my gold and silver Duke of Edinburgh\'s award which I thoroughly enjoyed completing and feel like this played a part in my love for walking in the mountains. I also achieved my grade 8 piano in December 2019. I feel that being elected as head girl has been a big accomplishment for me. I have achieved my silver Millennium Volunteers Award. ', 'special_skills' => 'I have good organisational and social skills which have been developed in my role of head girls. Working every Saturday in a bakery and serving customers whislt dealing with money has made me more outgoing and encouraged me to use my intiative. ', 'contrib_entertainment' => 'I already play piano in church and at weddings, so feel like this could contribute to entertainment as I am quite confident in this. Being a leader in Sunday school and other organisations I could contribute to entertainment by providing games.', 'reason_for_camp' => 'I have developed an interest in different cultures and religions through my studies of Spanish and Geography. I find it very intriguing to see other people\'s way of life especially if I was to go to a camp whereby we stayed in a Rotarian\'s home. I am keen to learn new skills and meet new friends all whilst travelling to a different part of the world. It is just such an unmissable opportunity.', 'personal_remarks' => 'Rotary can give me the opportunity to learn and become more aware of the world around me of which is invaluable to me.', 'place_of_birth' => 'Craigavon, Armagh. Northern Ireland', 'em_name' => 'Roland Kirkland', 'em_relationship' => 'Grandfather', 'em_htel' => '+44 28 3754 9757', 'em_mobile' => '', 'em_email' => '', 'country_citizenship' => null, 'image_location' => 'uploads/pict_app3918.png', 'date_of_app' => '2019-12-30 23:30:00'],
